    public override Dictionary<string, object> parseWsTrade(object trade, object market = null)
    {
        //
        //   [
        //         1894994106, // id
        //         1656151427.729706, // deal time
        //         "LTC_USDT", // symbol
        //         96624037337, // order id
        //         "56.78", // price
        //         "0.16717", // amount
        //         "0.0094919126", // fee
        //         '', // client order id
        //         "2", // side, 1 = sell, 2 = buy
        //         "2", // role, 1 = maker, 2 = taker
        //         "LTC" // fee asset
        //    ]
        //
        string? orderId = this.safeString(trade, 3);
        Int64? timestamp = this.safeTimestamp(trade, 1);
        string? id = this.safeString(trade, 0);
        string? price = this.safeString(trade, 4);
        string? amount = this.safeString(trade, 5);
        string? marketId = this.safeString(trade, 2);
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        Dictionary<string, object> fee = null;
        string? feeCost = this.safeString(trade, 6);
        if ((feeCost != null))
        {
            string? feeCurrencyId = this.safeString(trade, 10);
            object feeCurrencyCode = null;
            if ((feeCurrencyId != null))
            {
                feeCurrencyCode = this.safeCurrencyCode(feeCurrencyId);
            } else
            {
                feeCurrencyCode = (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null);
            }
            fee = new Dictionary<string, object>() {
                { "cost", feeCost },
                { "currency", feeCurrencyCode },
            };
        }
        Int64? rawSide = this.safeInteger(trade, 8);
        string? side = null;
        if ((rawSide == 1))
        {
            side = "sell";
        } else if ((rawSide == 2))
        {
            side = "buy";
        }
        Int64? role = this.safeInteger(trade, 9);
        string? takerOrMaker = null;
        if ((role == 1))
        {
            takerOrMaker = "maker";
        } else if ((role == 2))
        {
            takerOrMaker = "taker";
