    public override Dictionary<string, object> parseWsOrder(object order, IDictionary<string, object> market = null)
    {
        //
        //   {
        //         "id": 96433622651,
        //         "market": "LTC_USDT",
        //         "type": 1,
        //         "side": 2, //1- sell 2-buy
        //         "ctime": 1656092215.39375,
        //         "mtime": 1656092215.39375,
        //         "price": "25",
        //         "amount": "0.202",
        //         "taker_fee": "0.001",
        //         "maker_fee": "0.001",
        //         "left": "0.202",
        //         "deal_stock": "0",
        //         "deal_money": "0",
        //         "deal_fee": "0",
        //         "activation_price": "40",
        //         "activation_condition": "lte",
        //         "client_order_id": ''
        //         "status": 1, // 1 = new, 2 = update 3 = cancel or execute
        //    }
        //
        Int64? status = this.safeInteger(order, "status");
        string? marketId = this.safeString(order, "market");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        string? id = this.safeString(order, "id");
        string? clientOrderId = ((string)this.omitZero(this.safeString(order, "client_order_id")));
        string? price = this.safeString(order, "price");
        string? filled = this.safeString(order, "deal_stock");
        string? cost = this.safeString(order, "deal_money");
        string? stopPrice = this.safeString(order, "activation_price");
        string? rawType = this.safeString(order, "type");
        string? type = this.parseWsOrderType(rawType);
        string? amount = null;
        string? remaining = null;
        if (type == "market")
        {
            amount = this.safeString(order, "deal_stock");
            remaining = "0";
        } else
        {
            remaining = this.safeString(order, "left");
            amount = this.safeString(order, "amount");
        }
        Int64? timestamp = this.safeTimestamp(order, "ctime");
        Int64? lastTradeTimestamp = this.safeTimestamp(order, "mtime");
        string? symbol = ((string)(marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null));
        Int64? rawSide = this.safeInteger(order, "side");
        string side = "buy";
        if ((rawSide == 1))
        {
            side = "sell";
        }
        string? dealFee = this.safeString(order, "deal_fee");
        Dictionary<string, object> fee = null;
        if ((dealFee != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", this.parseNumber(dealFee) },
                { "currency", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null) },
            };
        }
        string? unifiedStatus = null;
        if (((status == 1)) || ((status == 2)))
        {
            unifiedStatus = "open";
        } else
        {
            if (Precise.stringEquals(remaining, "0"))
            {
                unifiedStatus = "closed";
            } else
            {
                unifiedStatus = "canceled";
            }
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "symbol", symbol },
            { "id", id },
            { "clientOrderId", clientOrderId },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", lastTradeTimestamp },
            { "type", type },
            { "timeInForce", null },
            { "postOnly", null },
            { "side", side },
            { "price", price },
            { "stopPrice", stopPrice },
            { "triggerPrice", stopPrice },
            { "amount", amount },
            { "cost", cost },
            { "average", null },
            { "filled", filled },
            { "remaining", remaining },
            { "status", unifiedStatus },
            { "fee", fee },
            { "trades", null },
        }, marketResolved);
    }

    public virtual string? parseWsOrderType(string? status)
